static const PromptData s_prompt_table[PROMPT_COUNT] = {
    { nullptr, 0 }, // PROMPT_NONE
    { s_PROMPT_ZERO, sizeof(s_PROMPT_ZERO) / sizeof(int16_t) }, // PROMPT_ZERO
    { s_PROMPT_ONE, sizeof(s_PROMPT_ONE) / sizeof(int16_t) }, // PROMPT_ONE
    { s_PROMPT_TWO, sizeof(s_PROMPT_TWO) / sizeof(int16_t) }, // PROMPT_TWO
    { s_PROMPT_THREE, sizeof(s_PROMPT_THREE) / sizeof(int16_t) }, // PROMPT_THREE
    { s_PROMPT_FOUR, sizeof(s_PROMPT_FOUR) / sizeof(int16_t) }, // PROMPT_FOUR
    { s_PROMPT_DEVICE, sizeof(s_PROMPT_DEVICE) / sizeof(int16_t) }, // PROMPT_DEVICE
    { s_PROMPT_DEVICES, sizeof(s_PROMPT_DEVICES) / sizeof(int16_t) }, // PROMPT_DEVICES
    { s_PROMPT_NEARBY, sizeof(s_PROMPT_NEARBY) / sizeof(int16_t) }, // PROMPT_NEARBY
    { s_PROMPT_MIDDLE, sizeof(s_PROMPT_MIDDLE) / sizeof(int16_t) }, // PROMPT_MIDDLE
    { s_PROMPT_FAR, sizeof(s_PROMPT_FAR) / sizeof(int16_t) }, // PROMPT_FAR
    { s_PROMPT_MIC_ON, sizeof(s_PROMPT_MIC_ON) / sizeof(int16_t) }, // PROMPT_MIC_ON
    { s_PROMPT_MIC_OFF, sizeof(s_PROMPT_MIC_OFF) / sizeof(int16_t) }, // PROMPT_MIC_OFF
    { s_PROMPT_VM_RECORDING, sizeof(s_PROMPT_VM_RECORDING) / sizeof(int16_t) }, // PROMPT_VM_RECORDING
    { s_PROMPT_VM_SENT, sizeof(s_PROMPT_VM_SENT) / sizeof(int16_t) }, // PROMPT_VM_SENT
    { s_PROMPT_VM_OUTBOX, sizeof(s_PROMPT_VM_OUTBOX) / sizeof(int16_t) }, // PROMPT_VM_OUTBOX
    { s_PROMPT_VM_INCOMING, sizeof(s_PROMPT_VM_INCOMING) / sizeof(int16_t) }, // PROMPT_VM_INCOMING
};

const PromptData& get_prompt(PromptId id) {
    if (id < PROMPT_COUNT) return s_prompt_table[id];
    return s_prompt_table[0];
}

void PromptQueue::push(PromptId id) {
    if (id == PROMPT_NONE || id >= PROMPT_COUNT) return;
    int next = (tail_ + 1) % kMaxQueue;
    if (next != head_) {
        queue_[tail_] = id;
        tail_ = next;
    }
}

void PromptQueue::clear() {
    head_ = tail_ = 0;
    sample_pos_ = 0;
}

bool PromptQueue::busy() const {
    return head_ != tail_;
}

bool PromptQueue::render(int16_t* out, size_t n, float vol_scale) {
    if (head_ == tail_) return false;
    size_t out_idx = 0;
    while (out_idx < n && head_ != tail_) {
        PromptId cur_id = queue_[head_];
        const PromptData& p = s_prompt_table[cur_id];
        if (!p.samples || sample_pos_ >= p.count) {
            head_ = (head_ + 1) % kMaxQueue;
            sample_pos_ = 0;
            continue;
        }
        size_t avail = p.count - sample_pos_;
        size_t take = (n - out_idx < avail) ? (n - out_idx) : avail;
        for (size_t i = 0; i < take; i++) {
            int32_t val = out[out_idx + i] + static_cast<int32_t>(p.samples[sample_pos_ + i] * vol_scale);
            out[out_idx + i] = clip16(val);
        }
        sample_pos_ += take;
        out_idx += take;
        if (sample_pos_ >= p.count) {
            head_ = (head_ + 1) % kMaxQueue;
            sample_pos_ = 0;
        }
    }
    return true;
}

